// Tus casos: una entrada y lo que esperás que salga.
// Cambialos por los cinco que trajiste de la clase 11.
const casos = [
  { entrada: "A-0007-00004410", esperado: "7-4410" },
  { entrada: "0001-00012345", esperado: "1-12345" },
  { entrada: "B-0010-00000420", esperado: "10-420" },
  { entrada: "Nº 0001-00012345", esperado: "1-12345" },
  { entrada: "A 0001 00012345", esperado: "1-12345" },
  { entrada: "sin número", esperado: "" },
];

return casos.map(c => ({ json: c }));

// Normaliza el número de factura: sin letra, sin ceros a la izquierda
// en cada tramo y con un guion entre punto de venta y número.
const limpio = String($json.entrada || '').replace(/[^0-9-]/g, '');
const obtenido = limpio.split('-').filter(p => p).map(p => Number(p)).join('-');

return { json: { ...$json, obtenido } };

const filas = $input.all().map(i => i.json);
const fallaron = filas.filter(f => !f.paso);

return [{
  json: {
    pasaron: filas.length - fallaron.length,
    de: filas.length,
    fallaron: fallaron.map(f => f.entrada + ' -> dio "' + f.obtenido + '", esperaba "' + f.esperado + '"'),
  },
}];
